"""一句话主张，写成**能被判错**的那种。一条概念只断言一件事。"""
LEVEL = "L1"        # 地图的哪一块：L1 动作效果 / L2 阻挡 / L4 计数器 / L5 终止 / L6 运动物 / L7 观测
SCOPE = "只看 ACTIONx；换关返回 NA；读不出来返回 NA"
NOTE = ""           # 改版时写清**为什么**改
EVIDENCE = []       # 它所依据的 tid，**不能为空**（硬要求 1）

# from _lib import me, CELL        # 本局词汇：这些是假设，跟着概念一起被重审
# from geo import diff_cells       # 跨局几何：里面没有任何关于世界的断言


def assert_(prev, action, nxt, ctx=None):
    """检查器：让主张可判错。只许返回 "TRUE" / "FALSE" / "NA"。"""
    return "NA"


def apply(prev, action, ctx=None):
    """生成器（可选）：这条概念**敢生成**的那部分下一帧，只填它管得着的格子。

    返回 {(行, 列): 颜色} 或 None。
    不变量式的概念（「墙集合不变」）生成不了就别写 apply，只写 assert_。
    """
    return None
"""本局词汇：两条以上概念共用的判据写在这里。

**它们是假设，不是事实。** 改 `_lib` 不算改版，但依赖它的概念要一起重审 ——
两条概念都从同一个词取值再互相核对，S=1 不等于这个词被检验过。
要检验一个词，得有一条概念拿它和帧上**另一种**读法对。
"""
            out.append({"color": color, "n": len(comp), "bbox": bbox(comp), "cells": comp})
    return out


def diff(prev, nxt) -> list[tuple[int, int, int, int]]:
    """逐格差：[(row, col, 旧色, 新色)]。"""
    return [(r, c, u, v) for r, (a, b) in enumerate(zip(prev, nxt))
            for c, (u, v) in enumerate(zip(a, b)) if u != v]


def diff_groups(prev, nxt) -> dict[tuple[int, int], list[tuple[int, int]]]:
    """帧差按 (旧色, 新色) 分组：{(u, v): [(row, col), …]}，按格数降序。"""
    groups: dict[tuple[int, int], list[tuple[int, int]]] = {}
    for r, c, u, v in diff(prev, nxt):
        groups.setdefault((u, v), []).append((r, c))
    return dict(sorted(groups.items(), key=lambda kv: -len(kv[1])))


def diff_sum(prev, nxt) -> list[tuple[int, tuple[int, int, int, int]]]:
    """把「这条转移改了多少格」拆成整数和：帧差格子按八邻接分块，返回 [(格数, bbox)]。

    方法册「帧差拆整数和」：形如 总数 = 腾空 + 新占 + 计数器；分项的格数能直接定出
    可动对象的尺寸、以及有没有搭便车的计数器，比从图样上猜快得多、也可证伪得多。
    """
    cells = [(r, c) for r, c, _, _ in diff(prev, nxt)]
    return [(len(comp), bbox(comp)) for comp in components(cells, diag=True)]


def fold(g, k: int, phase: tuple[int, int] = (0, 0)) -> list[list[int]]:
    """按 k×k 折叠成 (H/k)×(W/k) 的格位图，每格报主色。phase = (行相位, 列相位)。

    方法册「坐标系+格点图」：测出步长是 k 格，就把整帧折成格位图，之后在格位图上看，不逐格读帧。
    """
    H, W = len(g), len(g[0]) if g else 0
    pr, pc = phase
    out = []
    for r0 in range(pr, H, k):
        row = []
        for c0 in range(pc, W, k):
            c: Counter = Counter()
            for r in range(r0, min(r0 + k, H)):
                c.update(g[r][c0:c0 + k])
            row.append(c.most_common(1)[0][0] if c else -1)
        out.append(row)
    return out


def fold_phase(g, k: int, colors) -> tuple[int, int]:
    """猜折叠相位：让指定颜色的格子在 k×k 块内最「整」（每块要么全是要么全不是）的 (行相位, 列相位)。"""
    cells = set(cells_of(g, colors))
    if not cells:
        return (0, 0)
    best, best_score = (0, 0), -1
    for pr in range(k):
        for pc in range(k):
            full = part = 0
            for r0 in range(pr, len(g), k):
                for c0 in range(pc, len(g[0]), k):
                    n = sum(1 for r in range(r0, min(r0 + k, len(g)))
                            for c in range(c0, min(c0 + k, len(g[0]))) if (r, c) in cells)
                    if n == k * k:
                        full += 1
                    elif n:
                        part += 1
            score = full - part
            if score > best_score:
                best, best_score = (pr, pc), score
    return best


def moved(prev, nxt, diag: bool = True) -> list[dict]:
    """前后帧里「整体位移」的块：prev 里消失的一块和 nxt 里出现的一块形状相同、颜色相同。

    返回 [{color, n, from_bbox, to_bbox, delta}]，delta = (d_row, d_col)。
    这是「谁动了、动了多少」的几何读法，不预设它是精灵。
    """
    gone = {}
    came = {}
    for r, c, u, v in diff(prev, nxt):
        gone.setdefault(u, []).append((r, c))
        came.setdefault(v, []).append((r, c))
    out = []
    for color in set(gone) & set(came):
        for a in components(gone[color], diag):
            sa = {(r - a[0][0], c - a[0][1]) for r, c in a}
            for b in components(came[color], diag):
                if len(a) != len(b):
                    continue
                sb = {(r - b[0][0], c - b[0][1]) for r, c in b}
                if sa == sb:
                    out.append({"color": color, "n": len(a), "from_bbox": bbox(a), "to_bbox": bbox(b),
                                "delta": (b[0][0] - a[0][0], b[0][1] - a[0][1])})
                    break
    return sorted(out, key=lambda d: -d["n"])


def unique_blobs(g, max_n: int = 60) -> list[dict]:
    """全图唯一的小物件：某种颜色只有一个连通块、且格数 ≤ max_n。方法册 L0：唯一的东西最可能是玩家或开关。"""
    out = []
    for color, n in hist(g).items():
        if n > max_n:
            continue
        comps = components(cells_of(g, color))
        if len(comps) == 1:
            out.append({"color": color, "n": n, "bbox": bbox(comps[0]), "cells": comps[0]})
    return out


def region(g, r0: int, c0: int, h: int, w: int, oob: int = -1) -> set[int]:
    """窗口 [r0, r0+h) × [c0, c0+w) 里出现的颜色集合；越界的格子记 oob。"""
    out = set()
    for r in range(r0, r0 + h):
        for c in range(c0, c0 + w):
            if 0 <= r < len(g) and 0 <= c < len(g[0]):
                out.add(g[r][c])
            else:
                out.add(oob)
    return out

